    {
      "keystrokes": "cat > summary.json << 'EOF'\n{\n  \"title\": \"Anti-Regression Rules\",\n  \"highlights\": [\n    \"Act first, report second\",\n    \"Use tools instead of talking about them\",\n    \"Fix broken things yourself\"\n  ]\n}\nEOF\\n",
      "duration": 0.2
